"""Build metric-first Markdown reports from completed validation evidence."""
from pathlib import Path
import json
import numpy as np,pandas as pd
E=Path(__file__).resolve().parent;D=E.parent
read=lambda x,**kw:pd.read_csv(E/x,**kw)
def val(x,d=2):
 try:
  if pd.isna(x):return '—'
  if isinstance(x,(float,np.floating)):return f'{x:.{d}f}'
  return str(x)
 except:return str(x)
def table(df,d=2):
 lines=['| '+' | '.join(map(str,df.columns))+' |','| '+' | '.join(['---']*len(df.columns))+' |']
 for _,r in df.iterrows():lines.append('| '+' | '.join(val(v,d).replace('|','/') for v in r)+' |')
 return '\n'.join(lines)
def write(n,s):(D/n).write_text(s.strip()+'\n')
def ucell(w):
 d=read(f'{w}_universe_cells.csv');sig=read(f'signal_{w}_summary.csv');sig=sig[(sig.horizon==3)&sig.rung.str.startswith('band_')].set_index('rung');bread=read(f'signal_{w}_band_breadth.csv').set_index('band');base=d[d.cell=='baseline'].iloc[0];rows=[]
 for _,r in d[d.cell!='baseline'].iterrows():
  name=r.cell;k=('band_0_'+name.split('_')[1] if name.startswith('top_') else name)
  z=sig.loc[k];b=bread.loc[k];rows.append({'Liquidity rank':name.replace('top_','1–').replace('band_','').replace('_','–'),'CAGR %':r.cagr_pct,'Sharpe':r.sharpe,'Δ Sharpe':r.sharpe-base.sharpe,'Max DD %':r.maxdd_pct,'Calmar':r.calmar,'Δ Calmar':r.calmar-base.calmar,'3m IC':z.mean_ic,'IC NW-t':z.nw_t,'Median eligible':b['median'],'Months <8 %':b.below8_pct})
 return pd.DataFrame(rows)
def dispersion(w):
 d=read(f'{w}_universe_cells.csv').set_index('cell').loc[[f'top_{n}' for n in [250,500,750,1000,1500]]];return {'Window':w,'Sharpe range':d.sharpe.max()-d.sharpe.min(),'Calmar range':d.calmar.max()-d.calmar.min(),'CAGR range pp':d.cagr_pct.max()-d.cagr_pct.min(),'DD range pp':d.maxdd_pct.max()-d.maxdd_pct.min(),'Minimum Sharpe':d.sharpe.min()}
def yrtable(w):
 d=read(f'{w}_universe_yearly.csv');d=d[d.cell.isin(['top_100','top_250','top_500','top_750','top_1000','top_1500','band_500_1000','band_1000_1500','band_1000_2000'])];d=d.pivot(index='year',columns='cell',values='return_pct').reset_index();return d.rename(columns=lambda c:str(c).replace('top_','1–').replace('band_','').replace('_','–'))
def loo(w):
 d=read(f'{w}_universe_returns.csv',index_col=0,parse_dates=True).iloc[:,0];rows=[]
 for yr in sorted(d.index.year.unique()):
  x=d[d.index.year!=yr];eq=(1+x).cumprod();eq0=np.r_[1.,eq.to_numpy()];cagr=eq.iloc[-1]**(252/len(x))-1;dd=(eq0/np.maximum.accumulate(eq0)-1).min();rows.append({'Year omitted':yr,'CAGR %':cagr*100,'Sharpe':x.mean()/x.std()*np.sqrt(252),'Max DD %':dd*100})
 return pd.DataFrame(rows)
def year_concentration(w):
 r=read(f'{w}_universe_returns.csv',index_col=0,parse_dates=True).iloc[:,0];v=np.log1p(r).groupby(r.index.year).sum();total=v.sum();return {'Window':w,'Positive years':int((v>0).sum()),'Negative years':int((v<0).sum()),'Top 2 positive years / total signed log growth %':100*v.nlargest(2).sum()/total if total>0 else np.nan}
A=json.loads((E/'data_audit.json').read_text()); F=json.loads((E/'fingerprint_result.json').read_text());
header='''**Scope and conventions.** Default `csm_stock_backtest_v3.py` configuration: 15 equal-weight target slots, 12/6-month volatility-normalized momentum, ADX and 52-week-high gates enabled, two-month rebalance, 0.30% one-way trade cost, plus the configured stops and corporate-action mask. Equity uses the engine’s intentional omission of exit-day P&L. Returns are historical simulations, not investable or blind OOS estimates. All final figures use a fixed OHLCV snapshot through 2026-10-30, created outside the source data folder and only read during the tests. The source folder was only read by this workflow.\n'''
stage1=header+f'''\n# Stage 1 — Universe and data integrity\n\n**Verdict: MAJOR DIVERGENCE in the 2015–2025 core universes; source adjustment and survivorship remain unresolved.** Core set = liquidity ranks 1–250, 1–500, 1–750, 1–1000 and 1–1500; separate bands are stress tests. A band `500–1000` means rank >500 and ≤1000. Ranks are based on the 63-day median traded value, with 21 observations minimum and a one-day shift. Filters use price > ₹10, listing age ≥252 observed bars within the loaded panel, circuit count ≤5, trend/falling-knife tests and the configured ADX/high52 gates. Portfolios start flat after a 450-calendar-day indicator warmup.\n\n## 2015–2025 universe sweep\n\n{table(ucell('late'),3)}\n\n## 2005–2014 universe sweep\n\n{table(ucell('early'),3)}\n\nΔ is each universe minus 1–1000 in the same window; negative Max DD is loss from peak. IC is the strategy’s 3-month cross-sectional Spearman IC, with HAC lag 3. Months <8 are computed on eligible factor breadth before requiring future observations.\n\n## Core-universe dispersion gates\n\n{table(pd.DataFrame([dispersion('early'),dispersion('late')]),3)}\n\n| Metric | Pass | Caution | Major divergence |\n| --- | --- | --- | --- |\n| Sharpe range | ≤0.35 | 0.35–0.60 | >0.60 |\n| Calmar range | ≤0.50 | 0.50–0.90 | >0.90 |\n| CAGR range | ≤8 pp | 8–15 pp | >15 pp |\n| Max DD range | ≤10 pp | 10–18 pp | >18 pp |\n| Any core Sharpe | >0 | — | ≤0 |\n\n## Returns by year and universe (%)\n\n{table(yrtable('early'),2)}\n\n{table(yrtable('late'),2)}\n\n## Year concentration: 1–1000

{table(pd.DataFrame([year_concentration('early'),year_concentration('late')]),2)}

The contribution of the two highest positive years is divided by total signed log growth, including down years. This is a concentration diagnostic, not an independent-sample test.

## Leave one year out: 1–1000\n\nThese are fixed-return-series diagnostics: the omitted year is removed, remaining daily returns are stitched together and annualized using 252 trading days. They are **not** fresh backtests or causal estimates of each year’s contribution.\n\n### 2005–2014\n\n{table(loo('early'),2)}\n\n### 2015–2025\n\n{table(loo('late'),2)}\n\n## Source audit\n\n| Check | Result | Meaning |\n| --- | --- | --- |\n| CSV files | {A['files']} | OHLCV source |\n| First / last valid close | {A['first']} / {A['last']} | Data observed |\n| Last seen >183 days before panel end | {A['last_seen_before_cutoff']} / {A['files']} ({A['last_seen_pct']:.2f}%) | Survivorship proxy; below the playbook’s 2% flag; not proof of delistings |\n| Duplicate-date observations | {A['counts'].get('duplicate_dates',0)} | Audit counts same-date rows; loader keeps the last exact duplicate timestamp |\n| Out-of-order observations | {A['counts'].get('out_of_order',0)} | Loader sorts date index |\n| Invalid/nonpositive closes | {A['counts'].get('nonpositive_or_missing',0)+A['counts'].get('invalid_close',0)} | Source audit count |\n| Adjacent valid close jumps below −40% or above +300% | {A['extreme_close_changes']} | Adjustment/anomaly review needed; not automatically confirmed errors or corporate actions |\n| Mask events / nullified bars, late load including warmup | {int(read('late_universe_cells.csv').iloc[0].events)} / {int(read('late_universe_cells.csv').iloc[0].masked_bars)} | Events are based on the loaded 2013–2025 panel; counts differ from the full-source audit |
| Source CSV metadata changed during validation | {F['metadata_changed']} | An independent updater changed the live source; added {F['added']}, removed {F['removed']}. Final tests use the frozen snapshot. |\n\nThe mask drops an event bar and its next bar in memory; it does **not** adjust a price series for a split or establish that remaining raw observations are economically comparable. It can also use the event-day close to alter that day’s opening fill: see [Stage 3](stage3_robustness_lookahead.md). All P&L and IC results retain this unresolved caveat. [Full audit](evidence/data_audit.json), [data manifest](evidence/data_manifest.csv), [universe runs](evidence/late_universe_cells.csv).\n'''
write('stage1_universe.md',stage1)
def signal3(w):
 d=read(f'signal_{w}_summary.csv');d=d[(d.horizon==3)&(~d.rung.str.startswith('band_'))];return d[['rung','n_months','mean_ic','icir','t_stat','nw_t','positive_ic_pct','average_names','months_lt8_pct']].rename(columns={'rung':'Rung','n_months':'Months','mean_ic':'Mean IC','icir':'ICIR','t_stat':'t-stat','nw_t':'NW-t','positive_ic_pct':'IC >0 %','average_names':'Mean names','months_lt8_pct':'<8 %'})
def horizons(w):
 d=read(f'signal_{w}_summary.csv');d=d[d.rung=='L3_tradeable'];return d[['horizon','n_months','mean_ic','icir','t_stat','nw_t','positive_ic_pct','monotone_pairs','spread_mean_pp','spread_nw_t','weighted_liquidity_ic']].rename(columns={'horizon':'Months ahead','n_months':'N','mean_ic':'IC','icir':'ICIR','t_stat':'t-stat','nw_t':'NW-t','positive_ic_pct':'IC >0 %','monotone_pairs':'Ordered pairs /4','spread_mean_pp':'Q5−Q1 pp','spread_nw_t':'Spread NW-t','weighted_liquidity_ic':'Liquidity-weighted IC'})
def accuracy_horizons(w):
 d=read(f'signal_{w}_accuracy_monthly.csv',parse_dates=['date']);rows=[]
 for h,g in d.groupby('horizon'):
  x=g.set_index('date').top_excess.sort_index();x=x.reindex(pd.date_range(x.index.min(),x.index.max(),freq='ME'));v=x.notna().to_numpy();n=int(v.sum());e=np.where(v,x.to_numpy()-x.mean(),0.);var=np.dot(e,e)/n
  for j in range(1,int(h)+1):var+=2*(1-j/(h+1))*np.dot(e[j:],e[:-j])/n
  rows.append({'Horizon months':h,'Months':n,'Selected mean':g.n_selected.mean(),'Above pool median %':g.stock_above_pool_median_pct.mean(),'Positive %':g.stock_positive_pct.mean(),'Excess vs pool pp':100*x.mean(),'Excess NW-t':x.mean()/np.sqrt(var/n) if var>0 else np.nan})
 return pd.DataFrame(rows)
sl3=read('signal_late_summary.csv').query("rung == 'L3_tradeable' and horizon == 3").iloc[0];sl0=read('signal_late_summary.csv').query("rung == 'L0_composite' and horizon == 3").iloc[0]
stage2=header+f'''\n# Stage 2 — Signal, horizons and decay\n\n**Verdict: FAIL for the configured 2015–2025 signal.** L0 NW-t = {sl0.nw_t:.2f} passes, configured L3 NW-t = {sl3.nw_t:.2f} falls below 2.0; quantile ordering is {int(sl3.monotone_pairs)}/4 and two years account for {sl3.top2_year_share_pct:.1f}% of total signed IC.\n\n**Gate:** L0 composite and configured L3 each require 3-month NW-t ≥2.0, and <8-name exclusions ≤15%. Five-quantile monotonicity and spread are separate checks. IC is cross-sectional Spearman correlation of the factor at month-end with subsequent close-to-close returns; Newey–West lag equals the forward horizon in months. The response is calculated on the in-memory masked prices, with the caveat in Stage 1.\n\n## 3-month filter ladder: 2015–2025\n\n{table(signal3('late'),4)}\n\n## 3-month filter ladder: 2005–2014\n\n{table(signal3('early'),4)}\n\nL0 = raw factor; L1 = price floor; L2 = price, liquidity, circuit and listing age; L3 before optional gates adds the strategy’s trend and falling-knife filters; configured L3 additionally applies ADX and 52-week-high. L4 adds positive 12-month momentum; L5 limits to the first 15 factor ranks. L5 IC measures ordering **within** the small selected group; it is not a portfolio return or an equal-weight top-vs-pool accuracy test.\n\n## Horizon decay: configured L3\n\n### 2015–2025\n\n{table(horizons('late'),4)}\n\n### 2005–2014\n\n{table(horizons('early'),4)}\n\nLiquidity-weighted IC weights ranked observations by median traded value; it is a **liquidity proxy**, not value-weighted IC by point-in-time market capitalization, which is unavailable. Equal-weighted quintile mean returns and ordering:\n\n{table(read('signal_late_quintiles.csv'),3)}\n\n## Annual IC concentration: configured L3, 3 months\n\n{table(pd.concat([read('signal_early_summary.csv').query("rung == 'L3_tradeable' and horizon == 3"),read('signal_late_summary.csv').query("rung == 'L3_tradeable' and horizon == 3")])[['window','n_months','mean_ic','top2_year_share_pct']],3)}\n\nTop-two share divides the two largest annual signed-IC sums by total signed IC, including negative years; >50% is flagged in the playbook.\n\n## Accuracy: theoretical signal picks by horizon\n\n### 2015–2025\n\n{table(accuracy_horizons('late'),3)}\n\n### 2005–2014\n\n{table(accuracy_horizons('early'),3)}\n\nTop-15 accuracy is the monthly mean fraction of selected stocks above their contemporaneous eligible-pool median and above zero. Top excess is their equal-weight forward return minus the pool’s; it is not the executed portfolio, because it ignores hysteresis, stops, trading and costs.\n\n## Time decay: configured L3, 3-month IC\n\n{table(pd.concat([read('signal_early_decay.csv'),read('signal_late_decay.csv'),read('signal_playbook_early_decay.csv'),read('signal_playbook_late_decay.csv')],ignore_index=True),4)}\n\nThe 2015–2025 comparison is 2023–2025 vs 2015–2022. The additional playbook-late comparison uses 2024–July 2026 signal months, with forward outcomes through October 2026, vs 2013–2023. Because these historical periods have already been examined, treat the latter as exploratory and do not treat its t-statistic as a fresh confirmation. Difference NW-t uses an intercept plus recent-period indicator with HAC lag 3. A non-significant difference is inconclusive, not proof the signal has remained stable. Results by year and three-year block make the sample size visible; annual tests are noisy.\n\n### Annual IC and selected-stock accuracy: 2015–2025\n\n{table(read('signal_late_years.csv'),4)}\n\n### Three-year blocks\n\n{table(read('signal_late_chunks.csv'),4)}\n\n## Forward-fill sensitivity\n\n{table(read('signal_late_ffill.csv'),4)}\n\nThis compares masked-price forward outcomes with forward-filled masked outcomes. Added observations and IC changes are an empirical missing-data sensitivity, **not** proof there is no survivorship bias. Raw-vs-masked outcomes on the same configured eligible signals are compared below; common-pair IC uses only tickers with both outcomes.

{table(pd.DataFrame([{'Months':len(read('mask_signal_comparison.csv')),'Raw IC':read('mask_signal_comparison.csv').raw_ic.mean(),'Masked IC':read('mask_signal_comparison.csv').clean_ic.mean(),'Raw IC, common names':read('mask_signal_comparison.csv').raw_common_ic.mean(),'Masked IC, common names':read('mask_signal_comparison.csv').clean_common_ic.mean(),'Raw-only name-months':int((read('mask_signal_comparison.csv').raw_n-read('mask_signal_comparison.csv').both_n).sum()),'Masked-only name-months':int((read('mask_signal_comparison.csv').clean_n-read('mask_signal_comparison.csv').both_n).sum())}]),4)}

[Monthly mask comparison](evidence/mask_signal_comparison.csv). [Detailed IC data](evidence/signal_late_summary.csv), [monthly IC](evidence/signal_late_series.csv).\n'''
write('stage2_signal.md',stage2)
def params(w):
 d=read(f'{w}_sweep_cells.csv');d=d[~d.cell.str.startswith(('ablate_','cost_'))];return d[['cell','cagr_pct','sharpe','calmar','maxdd_pct','turnover_pct']].rename(columns={'cell':'Configuration','cagr_pct':'CAGR %','sharpe':'Sharpe','calmar':'Calmar','maxdd_pct':'Max DD %','turnover_pct':'Turnover %/yr'})
def abl(w):
 d=read(f'{w}_sweep_cells.csv');d=d[(d.cell=='baseline')|d.cell.str.startswith('ablate_')].copy();r=d[d.cell=='baseline'].iloc[0]
 for col in ['sharpe','calmar','stability','average_dd_pct','turnover_pct']:d['Δ '+col+' %']=100*(d[col]/r[col]-1) if r[col]!=0 else np.nan
 cols=['cell','sharpe','Δ sharpe %','calmar','Δ calmar %','stability','Δ stability %','average_dd_pct','Δ average_dd_pct %','turnover_pct','Δ turnover_pct %'];d=d[cols];d.columns=['Ablation','Sharpe','Δ %','Calmar','Δ %','12m σ','Δ %','Avg DD %','Δ %','Turnover %','Δ %'];return d
def cost(w):
 d=read(f'{w}_sweep_cells.csv');d=d[(d.cell=='baseline')|d.cell.str.startswith('cost_')]
 return d[['cell','cagr_pct','sharpe','calmar','maxdd_pct','cost_drag_pct']]
def swings(w):
 d=read(f'{w}_sweep_cells.csv').set_index('cell');pairs={'Lookback 10–14 months':['lookback_10','lookback_12','lookback_14'],'Slots 12–18':['positions_12','positions_15','positions_18'],'Hard stop 12–18%':['stop_0.12','stop_0.15','stop_0.18'],'High52 0.68–1.00 (bounded)':['high52_0.68','high52_0.85','high52_1.00']};adx=read(f'{w}_adx_cells.csv').set_index('cell').loc[['adx_16','adx_20','adx_24']].sharpe;return pd.DataFrame([{'Parameter':k,'Sharpe min':d.loc[v].sharpe.min(),'Sharpe max':d.loc[v].sharpe.max(),'Swing':d.loc[v].sharpe.max()-d.loc[v].sharpe.min(),'≤0.4': 'PASS' if d.loc[v].sharpe.max()-d.loc[v].sharpe.min()<=.4 else 'FAIL'} for k,v in pairs.items()]+[{'Parameter':'ADX 16–24','Sharpe min':adx.min(),'Sharpe max':adx.max(),'Swing':adx.max()-adx.min(),'≤0.4':'PASS' if adx.max()-adx.min()<=.4 else 'FAIL'}])
caus=json.loads((E/'execution_causality.json').read_text());prefix=read('prefix_tests.csv');par=read('actual_strategy_parity.csv');earlyextra=read('early_sweep_cells.csv');
stage3=header+f'''\n# Stage 3 — Robustness, ablation and lookahead\n\n**Verdict: FAIL the no-lookahead requirement.** The following are deterministic tests of the actual unmodified engine. Same known-at-open state and opening price were held fixed; only later bar information changed. They show timing failures independent of the intentionally omitted exit-day P&L.\n\n| Test | Same open / later-bar variation | Observed outcome | Verdict |\n| --- | --- | --- | --- |\n| Stop before scheduled open exit | Open 100; later low 90 vs 80 | REBAL_EXIT at 100 and next-day holding {caus['stop_order']['later_low_90']['holdings_next_day']} vs HARD_STOP_HIT at 84.745 and next-day holding {caus['stop_order']['later_low_80']['holdings_next_day']} | FAIL |\n| Corporate-action mask at open | Open 100; later close 100 vs 500 | Entry fill {caus['mask_at_open']['no_large_close_jump']['entry_price']} vs {caus['mask_at_open']['close_later_500']['entry_price']} (stale prior open) | FAIL |\n| Full-day circuit check at open | Open 100; later high/low differ vs are equal | Held on scheduled day {caus['circuit_at_open']['later_range_nonzero']['held_on_entry_day']} vs {caus['circuit_at_open']['later_range_zero']['held_on_entry_day']}; entry delayed a day | FAIL |\n\nStop ordering arises because the loop checks the complete day’s low before processing target exits at the open. The mask knows an event from its close, yet removes the event day’s open and the engine forward-fills it. The circuit condition uses completed-day high and low for opening decisions. These are proven synthetic counterexamples, not claims that every historical trade is affected. [Reproducible tests](evidence/test_execution_causality.py); see [engine](../csm_stock_backtest_v3.py) and [strategy](../csm_stock_strategy_v3.py).\n\n## Actual-class parity and history truncation\n\n{table(par,8)}\n\n{table(prefix,8)}\n\nPrefix checks compare historical factor values, eligible masks, position targets and ATR to independently truncated runs. Passing them does not validate open execution timing. Actual-class parity compares the default v3 class and engine against the reconstructed baseline; both use identical flat-start selection.\n\n## Parameter sensitivity: 2015–2025\n\n{table(params('late'),3)}\n\n## Parameter sensitivity: 2005–2014\n\n{table(params('early'),3)}\n\n## ADX threshold sensitivity\n\n{table(pd.concat([read('early_adx_cells.csv'),read('late_adx_cells.csv')],ignore_index=True)[['window','cell','cagr_pct','sharpe','calmar','maxdd_pct']],3)}\n\nADX thresholds 16 and 24 are ±20% around the configured 20; 12 and 28 are ±40%.\n\n## ±20% Sharpe sensitivity\n\n### 2015–2025\n\n{table(swings('late'),3)}\n\n### 2005–2014\n\n{table(swings('early'),3)}\n\nThe 2-month rebalance setting is discrete, so 1 and 3 months are ±50% stress tests rather than ±20% tests. High52 cannot exceed 1.00 when defined as close divided by its rolling high: the +20% point is unattainable, so 1.00 is a boundary sensitivity, not a symmetric +20% point. Lookback 10/14 are the nearest integer points to ±20%.\n\n## Ablation scorecard: 2015–2025\n\n{table(abl('late'),3)}\n\n## Ablation scorecard: 2005–2014\n\n{table(abl('early'),3)}\n\nΔ is relative to baseline. Lower 12-month rolling-return standard deviation, average drawdown depth and turnover are preferable. Playbook disqualification limits: Sharpe/Calmar regression >15%; stability/average DD worsening >20%; turnover increase >25%. These are diagnostic single-feature removals, not a recommendation to optimize against the test window.\n\n## Transaction-cost stress (fully rerun share engine)\n\n### 2015–2025\n\n{table(cost('late'),3)}\n\n### 2005–2014\n\n{table(cost('early'),3)}\n\nCosts are 0.3%, 0.6%, 0.9% one way on traded value, respectively. Stop-fill assumptions remain those of the source engine. Higher transaction costs do not cure the timing or adjustment issues. [Early sweep](evidence/early_sweep_cells.csv), [late sweep](evidence/late_sweep_cells.csv), [original early split sweep](evidence/playbook_early_sweep_cells.csv), [original late split sweep](evidence/playbook_late_sweep_cells.csv).\n'''
write('stage3_robustness_lookahead.md',stage3)
def baseline(w,mode='universe'):
 d=read(f'{w}_{mode}_cells.csv');return d[d.cell=='baseline'].iloc[0]
def icvals(w):
 d=read(f'signal_{w}_summary.csv');d=d[d.horizon==3].set_index('rung');return d.loc['L0_composite','nw_t'],d.loc['L3_tradeable','nw_t']
def split_table(a,b):
 x=baseline(*a);y=baseline(*b);l0,l3=icvals(b[0]);checks=[('Sharpe OOS/IS',y.sharpe/x.sharpe,'≥0.60'),('Calmar OOS/IS',y.calmar/x.calmar,'≥0.60'),('CAGR OOS/IS',y.cagr_pct/x.cagr_pct,'≥0.50'),('Max DD OOS/IS',abs(y.maxdd_pct)/abs(x.maxdd_pct),'≤1.50'),('OOS Sharpe',y.sharpe,'>0'),('OOS L0 3m IC NW-t',l0,'≥1.50'),('OOS L3 3m IC NW-t',l3,'≥1.50')];return pd.DataFrame([{'Metric':n,'Result':v,'Gate':g,'Verdict':('CAUTION' if n in ('Sharpe OOS/IS','Calmar OOS/IS') and .4<=v<.6 else ('PASS' if (v>=float(g[1:]) if g.startswith('≥') else v<=float(g[1:]) if g.startswith('≤') else v>float(g[1:])) else 'FAIL')) if np.isfinite(v) else 'UNAVAILABLE'} for n,v,g in checks]+[{'Metric':'Δ Sharpe (OOS − IS)','Result':y.sharpe-x.sharpe,'Gate':'informational','Verdict':'—'},{'Metric':'Δ Calmar (OOS − IS)','Result':y.calmar-x.calmar,'Gate':'informational','Verdict':'—'}])
def score(w,mode):
 r=baseline(w,mode);return {'Window':w,'First entry':r.first_entry,'CAGR %':r.cagr_pct,'Sharpe':r.sharpe,'Sortino':r.sortino,'Max DD %':r.maxdd_pct,'Calmar':r.calmar,'Vol %':r.vol_pct,'Exposure %':r.exposure_pct,'Turnover %/yr':r.turnover_pct,'Trades':r.trades}
base_metrics=pd.DataFrame([score('early','universe'),score('late','universe'),score('playbook_early','baseline'),score('playbook_late','baseline'),score('full','baseline')]);
